public List<List<Integer>> permute(int[] nums) {
    List<List<Integer>> res = new ArrayList<>();
    if (nums == null) return res;
    boolean[] used = new boolean[nums.length];
    List<Integer> current = new ArrayList<>();
    backtrack(nums, used, current, res);
    return res;
}

private void backtrack(int[] nums, boolean[] used, List<Integer> current, List<List<Integer>> res) {
    if (current.size() == nums.length) {
        res.add(new ArrayList<>(current));
        return;
    }
    for (int i = 0; i < nums.length; i++) {
        if (!used[i]) {
            used[i] = true;
            current.add(nums[i]);
            backtrack(nums, used, current, res);
            current.remove(current.size() - 1);
            used[i] = false;
        }
    }
}

public int findLargestSubstring(List<String> strings) {
    if (strings == null || strings.isEmpty()) {
        return 0;
    }
    int n = strings.size();
    // Precompute substring sets for each string
    List<Set<String>> substringSets = new ArrayList<>(n);
    for (String s : strings) {
        Set<String> set = new HashSet<>();
        int len = s.length();
        for (int i = 0; i < len; i++) {
            for (int j = i + 1; j <= len; j++) {
                set.add(s.substring(i, j));
            }
        }
        substringSets.add(set);
    }
    // Generate all substrings of the first string
    String first = strings.get(0);
    int firstLen = first.length();
    if (firstLen == 0) {
        return 0;
    }
    Set<String> firstSubstrings = new HashSet<>();
    for (int i = 0; i < firstLen; i++) {
        for (int j = i + 1; j <= firstLen; j++) {
            firstSubstrings.add(first.substring(i, j));
        }
    }
    // Sort substrings by length descending
    List<String> candidates = new ArrayList<>(firstSubstrings);
    candidates.sort((a, b) -> Integer.compare(b.length(), a.length()));
    // Check each candidate
    for (String candidate : candidates) {
        String rev = new StringBuilder(candidate).reverse().toString();
        boolean ok = true;
        for (Set<String> set : substringSets) {
            if (!set.contains(candidate) && !set.contains(rev)) {
                ok = false;
                break;
            }
        }
        if (ok) {
            return candidate.length();
        }
    }
    return 0;
}

public static int countOilDeposits(char[][] grid) {
    if (grid == null || grid.length == 0 || grid[0].length == 0) {
        return 0;
    }
    int rows = grid.length;
    int cols = grid[0].length;
    boolean[][] visited = new boolean[rows][cols];
    int deposits = 0;
    for (int r = 0; r < rows; r++) {
        for (int c = 0; c < cols; c++) {
            if (grid[r][c] == '@' && !visited[r][c]) {
                deposits++;
                dfs(grid, visited, r, c, rows, cols);
            }
        }
    }
    return deposits;
}

private static void dfs(char[][] grid, boolean[][] visited, int r, int c, int rows, int cols) {
    int[] dr = {-1, -1, -1, 0, 0, 1, 1, 1};
    int[] dc = {-1, 0, 1, -1, 1, -1, 0, 1};
    visited[r][c] = true;
    for (int i = 0; i < 8; i++) {
        int nr = r + dr[i];
        int nc = c + dc[i];
        if (nr >= 0 && nr < rows && nc >= 0 && nc < cols) {
            if (grid[nr][nc] == '@' && !visited[nr][nc]) {
                dfs(grid, visited, nr, nc, rows, cols);
            }
        }
    }
}

