public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    if (java.util.Arrays.equals(start, end)) return "can be travelled";
    java.util.Map<String, java.util.List<String>> adj = new java.util.HashMap<>();
    String startKey = java.util.Arrays.toString(start);
    String endKey = java.util.Arrays.toString(end);
    adj.putIfAbsent(startKey, new java.util.ArrayList<>());
    adj.putIfAbsent(endKey, new java.util.ArrayList<>());
    for (int[] path : paths) {
        if (path.length != 2 * n) continue;
        int[] coord1 = java.util.Arrays.copyOfRange(path, 0, n);
        int[] coord2 = java.util.Arrays.copyOfRange(path, n, 2 * n);
        String key1 = java.util.Arrays.toString(coord1);
        String key2 = java.util.Arrays.toString(coord2);
        adj.computeIfAbsent(key1, k -> new java.util.ArrayList<>()).add(key2);
        adj.computeIfAbsent(key2, k -> new java.util.ArrayList<>()).add(key1);
    }
    java.util.Queue<String> queue = new java.util.LinkedList<>();
    java.util.Set<String> visited = new java.util.HashSet<>();
    queue.add(startKey);
    visited.add(startKey);
    while (!queue.isEmpty()) {
        String cur = queue.poll();
        java.util.List<String> neighbors = adj.get(cur);
        if (neighbors == null) continue;
        for (String nb : neighbors) {
            if (!visited.contains(nb)) {
                if (nb.equals(endKey)) return "can be travelled";
                visited.add(nb);
                queue.add(nb);
            }
        }
    }
    return "cannot be travelled";
}

