}

private int dfs(int node, java.util.List<Integer>[] graph, boolean[] visited, boolean[] hasApple) {
    visited[node] = true;
    int time = 0;
    for (int nei : graph[node]) {
        if (!visited[nei]) {
            int sub = dfs(nei, graph, visited, hasApple);
            if (hasApple[nei] || sub > 0) {
                time += sub + 2;
            }
        }
    }
    return time;
}

public String sortString(String s) {
    int[] freq = new int[26];
    for (char c : s.toCharArray()) {
        freq[c - 'a']++;
    }
    StringBuilder result = new StringBuilder();
    int total = s.length();
    while (result.length() < total) {
        // Ascending pass: pick smallest available characters
        for (int i = 0; i < 26; i++) {
            if (freq[i] > 0) {
                result.append((char) (i + 'a'));
                freq[i]--;
            }
        }
        // Descending pass: pick largest available characters
        for (int i = 25; i >= 0; i--) {
            if (freq[i] > 0) {
                result.append((char) (i + 'a'));
                freq[i]--;
            }
        }
    }
    return result.toString();
}

public boolean splitArraySameAverage(int[] nums) {
    int n = nums.length;
    if (n < 2) return false;
    int totalSum = 0;
    for (int num : nums) totalSum += num;
    int maxK = n / 2;
    java.util.HashSet<Integer>[] dp = new java.util.HashSet[maxK + 1];
    for (int k = 0; k <= maxK; k++) dp[k] = new java.util.HashSet<>();
    dp[0].add(0);
    for (int num : nums) {
        for (int k = maxK; k >= 1; k--) {
            java.util.HashSet<Integer> prev = dp[k - 1];
            if (prev.isEmpty()) continue;
            java.util.HashSet<Integer> curr = dp[k];
            for (int sum : prev) {
                curr.add(sum + num);
            }
        }
    }
    for (int k = 1; k <= maxK; k++) {
        if ((totalSum * k) % n != 0) continue;
        int target = (totalSum * k) / n;
        if (dp[k].contains(target)) return true;
    }
    return false;
}

public int minCostClimbingStairs(int[] cost) {
    int n = cost.length;
    if (n == 0) return 0;
    if (n == 1) return cost[0];
    if (n == 2) return Math.min(cost[0], cost[1]);

    int[] dp = new int[n];
    dp[0] = cost[0];
    dp[1] = cost[1];
    for (int i = 2; i < n; i++) {
        dp[i] = cost[i] + Math.min(dp[i - 1], dp[i - 2]);
    }
    return Math.min(dp[n - 1], dp[n - 2]);
}

