public boolean hasAllCodes(String s, int k) {
    int n = s.length();
    if (k == 0) return true;
    int total = 1 << k;
    if (n < total) return false;
    boolean[] seen = new boolean[total];
    int mask = total - 1;
    int code = 0;
    // Build the first code
    for (int i = 0; i < k; i++) {
        code = (code << 1) | (s.charAt(i) - '0');
    }
    seen[code] = true;
    // Slide over the string
    for (int i = k; i < n; i++) {
        code = ((code << 1) & mask) | (s.charAt(i) - '0');
        seen[code] = true;
    }
    // Check if all codes were seen
    for (boolean present : seen) {
        if (!present) return false;
    }
    return true;
}

