    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        if (c == '(') {
            balance++;
        } else if (c == ')') {
            if (balance == 0) {
                insertions++;
            } else {
                balance--;
            }
        }
    }
    insertions += balance;
    return insertions;
}

